import os, glob, re

def load_grids():
    """Load all grid data from session logs"""
    session_dir = os.environ.get('RLM_SESSION_DIR')
    if not session_dir:
        return {}

    session_name = os.path.basename(session_dir)
    log_path = os.path.join(session_dir, f'..', '..', 'sessions', session_name, '.jsonl')
    # Try the main session log
    log_path = session_dir.replace('state', 'sessions').split('/')[0]

    # Find the jsonl file
    for root, dirs, files in os.walk(session_dir):
        for f in files:
            if f.endswith('.jsonl'):
                path = os.path.join(root, f)
                try:
                    with open(path, 'r') as fp:
                        content = fp.read()
                        grids = {}
                        for line in content.split('\n'):
                            if line.startswith('Demo pair') or line.startswith('Test input'):
                                match = re.search(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', line)
                                if match:
                                    key = match.group(1).rstrip(':')
                                    dims = (int(match.group(2)), int(match.group(3)))
                                    grids[key] = dims
                        return grids
                except:
                    pass
    return {}

